<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Estoque</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><?php include __DIR__.'/../partials/menu.php';?><main class="main"><div class="topline"><div><h1>Estoque</h1><p class="muted">Controle de entradas e saídas.</p></div><div><a class="btn primary" href="entrada.php">+ Entrada</a> <a class="btn danger-btn" href="saida.php">− Saída</a></div></div><div class="panel"><table><thead><tr><th>Código</th><th>Produto</th><th>Unidade</th><th>Estoque</th><th>Mínimo</th><th>Status</th></tr></thead><tbody><?php foreach($produtos as $p):$baixo=$p['estoque']<=$p['estoque_minimo'];?><tr><td><?=htmlspecialchars($p['codigo'])?></td><td><?=htmlspecialchars($p['nome'])?></td><td><?=htmlspecialchars($p['unidade'])?></td><td><?=number_format($p['estoque'],2,',','.')?></td><td><?=number_format($p['estoque_minimo'],2,',','.')?></td><td><span class="tag <?=$baixo?'red':'green'?>"><?=$baixo?'BAIXO':'NORMAL'?></span></td></tr><?php endforeach;?></tbody></table></div></main></body></html>